function slugify(value:string){return value.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'presentacion';}
function safeAssetName(name:string){return name.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9._-]+/g,'-');}
function clone<T>(value:T):T{return structuredClone(value);}
/** MIME a partir de la extensión del asset; los bytes que guardamos no lo conservan. */
function mimeForAsset(path:string){
  const ext=path.toLowerCase().split('.').pop()??'';
  if(ext==='jpg'||ext==='jpeg')return 'image/jpeg';
  if(ext==='webp')return 'image/webp';
  if(ext==='gif')return 'image/gif';
  if(ext==='svg')return 'image/svg+xml';
  return 'image/png';
}
function arrangeCanvas(canvas:CanvasElement[], ids:string[], mode:'row'|'column'|'grid', gap=2, padding=5){
  const targets=canvas.filter(x=>ids.includes(x.id)&&x.type!=='connector'&&!x.hidden); if(!targets.length)return canvas;
  const order=targets.slice().sort((a,b)=>(a.zIndex??0)-(b.zIndex??0)); const map=new Map<string,{x:number;y:number;w:number;h:number}>();
  if(mode==='row'){const usable=100-padding*2-gap*(order.length-1),w=Math.max(5,usable/order.length),h=Math.min(60,Math.max(...order.map(x=>x.h)));order.forEach((x,i)=>map.set(x.id,{x:padding+i*(w+gap),y:50-h/2,w,h}));}
  else if(mode==='column'){const usable=100-padding*2-gap*(order.length-1),h=Math.max(5,usable/order.length),w=Math.min(80,Math.max(...order.map(x=>x.w)));order.forEach((x,i)=>map.set(x.id,{x:50-w/2,y:padding+i*(h+gap),w,h}));}
  else {const cols=Math.ceil(Math.sqrt(order.length)),rows=Math.ceil(order.length/cols),w=(100-padding*2-gap*(cols-1))/cols,h=(100-padding*2-gap*(rows-1))/rows;order.forEach((x,i)=>map.set(x.id,{x:padding+(i%cols)*(w+gap),y:padding+Math.floor(i/cols)*(h+gap),w,h}));}
  return canvas.map(x=>map.has(x.id)?{...x,...map.get(x.id)!}:x);
}
type HistoryEntry={doc:PresentationDocument;label:string;time:string};
